// Generated by Stillmark (`stillmark notify hook install --agent=opencode`).
// It runs `stillmark notify run-hook --agent=opencode` when an OpenCode run ends.
import { spawn } from "node:child_process";
import { Plugin } from "@opencode/plugin";

const Command: readonly string[] = ["stillmark", "notify", "run-hook", "--agent=opencode"];

type Status = "done" | "failed" | "waiting" | "stopped";

interface EventPayload {
    readonly type?: string;
    readonly location?: {
        readonly directory?: string;
    };
    readonly data?: {
        readonly sessionID?: string;
        readonly assistantMessageID?: string;
        readonly text?: string;
        readonly error?: {
            readonly message?: string;
        };
    };
}

/**
 * Sends the finish payload without keeping the agent waiting.
 */
function send(status: Status, root: string | undefined, summary: string | undefined): void {
    try {
        const [executable, ...args] = Command;
        const child = spawn(executable, args, {
            detached: true,
            stdio: ["pipe", "ignore", "ignore"],
            windowsHide: true
        });

        child.stdin?.end(JSON.stringify({ status, root, summary }));
        child.unref();
    } catch {
        // A notification must never break the agent.
    }
}

export default Plugin.define({
    id: "stillmark-notify",
    async setup(context) {
        const controller = new AbortController();
        const replies = new Map<string, { messageID: string; text: string }>();

        void (async () => {
            try {
                for await (const raw of context.event.subscribe({ signal: controller.signal })) {
                    const event = raw as unknown as EventPayload;
                    const sessionID = event.data?.sessionID;

                    if (!sessionID) {
                        continue;
                    }

                    const root = event.location?.directory ?? context.location?.directory;

                    if (event.type === "session.text.ended" && typeof event.data?.text === "string") {
                        const messageID = event.data.assistantMessageID ?? "";
                        const previous = replies.get(sessionID);
                        const text = previous && previous.messageID === messageID
                            ? `${previous.text}\n${event.data.text}`
                            : event.data.text;

                        replies.set(sessionID, { messageID, text });
                    } else
                    if (event.type === "session.execution.succeeded") {
                        const reply = replies.get(sessionID)?.text;
                        const status: Status = reply?.trim().endsWith("?") ? "waiting" : "done";

                        replies.delete(sessionID);
                        send(status, root, reply);
                    } else
                    if (event.type === "session.execution.failed") {
                        replies.delete(sessionID);
                        send("failed", root, event.data?.error?.message);
                    } else
                    if (event.type === "session.execution.interrupted") {
                        replies.delete(sessionID);
                        send("stopped", root, undefined);
                    }
                }
            } catch {
                // The stream closes when OpenCode shuts down or reloads the plugin.
            }
        })();

        return () => {
            controller.abort();
        };
    }
});
